   \[
   =\frac{2\sum_{k=1}^{n-2}k(n-k-1)-(n-1)\sum_{k=1}^{n-1}k}{2n}
   =\frac{2\left(\sum_{k=1}^{n-2}kn - \sum_{k=1}^{n-2}k^2 - \sum_{k=1}^{n-2}k\right) - (n-1)\sum_{k=1}^{n-1}k}{2n}
